select n.nspname || '.' || c.relname as tabla, c.relrowsecurity as rls, (select count(*) from pg_policy p where p.polrelid = c.oid) as politicas, has_table_privilege('anon', c.oid, 'SELECT') as anon_lee, has_table_privilege('anon', c.oid, 'INSERT,UPDATE,DELETE') as anon_escribe, has_table_privilege('authenticated', c.oid, 'SELECT') as auth_lee, has_table_privilege('authenticated', c.oid, 'INSERT,UPDATE,DELETE') as auth_escribe, has_table_privilege('service_role', c.oid, 'SELECT,INSERT,UPDATE,DELETE') as service_ok, (select array_agg(a::text order by a::text) from unnest(c.relacl) a)::text as acl, (select count(*) from pg_class c2 join pg_namespace n2 on n2.oid = c2.relnamespace where c2.relkind in ('r','p') and n2.nspname in ('mos','me','wh','public') and not c2.relrowsecurity and (has_table_privilege('anon', c2.oid, 'SELECT') or has_table_privilege('authenticated', c2.oid, 'SELECT'))) as total_alertas_advisor_rls from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.oid in ('mos.accesos_dispositivos'::regclass, 'mos.extension_requests'::regclass, 'mos.purgas_historicas'::regclass, 'mos.sunat_voucher'::regclass, 'mos.sunat_cronograma'::regclass, 'me.zona_por_activar_descartado'::regclass, 'mos.personal_alias_me'::regclass) order by 1
